import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Monitor de Relatórios","description":"","frontmatter":{"title":"Monitor de Relatórios","id":"eproc-monitor-relatorio","plataforma":"eproc","grupo":"Monitoramento","plano":"free","desde":"1.2.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-monitor-relatorio"}]]},"headers":[],"relativePath":"funcionalidades/eproc-monitor-relatorio.md","filePath":"funcionalidades/eproc-monitor-relatorio.md"}'),t={name:"funcionalidades/eproc-monitor-relatorio.md"};function i(l,a,d,n,c,u){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="monitor-de-relatorios" tabindex="-1">Monitor de Relatórios <a class="header-anchor" href="#monitor-de-relatorios" aria-label="Permalink to &quot;Monitor de Relatórios&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Permite marcar processos de um relatório para acompanhar. Na próxima vez que o processo aparecer no relatório, o eploc destaca as colunas que mudaram desde a marcação. Se nada mudou, a linha fica esmaecida, para você focar no que andou.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, Relatório Geral de Processos. O gerenciamento fica nas configurações do eploc, no card do recurso (&quot;Gerenciar colunas excluídas e processos monitorados&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Gere o Relatório Geral.</li><li>Passe o mouse sobre a linha de um processo e clique no ícone de olho (&quot;Monitorar este processo&quot;). Para marcar todos os processos da página, clique no botão <strong>eploc</strong>, no fim da barra acima da tabela, e escolha &quot;Monitorar todos os processos desta página&quot;. No mesmo menu, &quot;Parar de monitorar os processos desta página&quot; desfaz isso.</li><li>Nas próximas vezes em que gerar o relatório: <ul><li>as células que mudaram ficam destacadas, com a marca &quot;NOVO&quot;;</li><li>as linhas sem mudança ficam esmaecidas.</li></ul></li><li>Depois de ver a mudança, use &quot;Marcar alteração como vista (continuar monitorando)&quot;. Para encerrar o acompanhamento, use &quot;Parar de monitorar este processo&quot;.</li><li>No gerenciador, você pode excluir colunas da comparação (por exemplo, colunas que mudam todo dia) e ver ou remover os processos monitorados.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Guardar o valor anterior de cada coluna alterada (cifrado, só neste dispositivo) para mostrá-lo ao passar o mouse</td><td>desligada</td><td>Ao passar o mouse sobre a marca &quot;NOVO&quot;, mostra o valor de antes. Desligada, o eploc guarda só uma impressão digital (hash) de cada valor, nunca o conteúdo.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O acompanhamento é separado por perfil/unidade do eproc.</li><li>Com a opção do valor anterior desligada, não há como saber qual era o valor antigo, só que ele mudou.</li><li>O valor anterior fica cifrado e só neste computador. Ele não entra no backup, então não aparece em outro computador.</li><li>Na coluna de localizadores, mudar só a ordem dos localizadores não conta como alteração.</li></ul>',11)]))}const h=o(t,[["render",i]]);export{p as __pageData,h as default};
